module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus('connecting', 'Connecting WebSocket...');
    },
    onTransportReady: function(transport, config) {
        engine.setStatus('connected', 'Connected');
        engine.setVariable('connection_state', 'ready');
    },
    onAction: function(transport, actionId, params) {
        if (actionId === 'call_method') {
            transport.sendJSON({
                jsonrpc: '2.0',
                method: params.method,
                id: Date.now()
            });
            return 'Dispatched ' + params.method;
        }
        return 'Unknown action';
    },
    onMessage: function(transport, text, bytes) {
        try {
            var msg = JSON.parse(text);
            engine.log('WS << ' + JSON.stringify(msg));
        } catch(e) {}
    },
    onDisconnect: function() {
        engine.setStatus('disconnected', 'WS Closed');
        engine.setVariable('connection_state', 'closed');
    }
};
